//! Script-tree builder tests. Anchor: every `scriptPubKey` row of BIP341's
//! `wallet-test-vectors.json` that has a `scriptTree` (`tree_vectors.zig`,
//! generated by `tools/gen_tree_vectors.py`): leaf hashes, Merkle root, tweak,
//! output key, scriptPubKey and EVERY control block, byte-exact — from both
//! the explicit-shape and the depth-list entry point.

const std = @import("std");
const bip340 = @import("bip340");
const taproot = @import("root.zig");
const tree = @import("tree.zig");
const v = @import("tree_vectors.zig");

const testing = std.testing;
const ta = testing.allocator;

fn hexAlloc(hex: []const u8) ![]u8 {
    const out = try ta.alloc(u8, hex.len / 2);
    errdefer ta.free(out);
    _ = try std.fmt.hexToBytes(out, hex);
    return out;
}

fn hex32(hex: []const u8) ![32]u8 {
    var out: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&out, hex);
    return out;
}

/// Assert every published value of `row` against `info`; returns how many
/// control blocks were compared.
fn checkRow(row: v.Row, info: tree.SpendInfo) !usize {
    try testing.expectEqualSlices(u8, &try hex32(row.merkle_root), &info.merkle_root.?);
    try testing.expectEqualSlices(u8, &try hex32(row.tweak), &info.tweak);
    try testing.expectEqualSlices(u8, &try hex32(row.tweaked_pubkey), &info.output.x);
    const spk = try hexAlloc(row.script_pub_key);
    defer ta.free(spk);
    try testing.expectEqual(@as(usize, 34), spk.len);
    try testing.expectEqualSlices(u8, &[_]u8{ 0x51, 0x20 }, spk[0..2]);
    try testing.expectEqualSlices(u8, spk[2..], &info.output.x);

    try testing.expectEqual(row.leaf_hashes.len, info.leaves.len);
    try testing.expectEqual(row.control_blocks.len, info.leaves.len);
    for (info.leaves, 0..) |leaf, i| {
        try testing.expectEqualSlices(u8, &try hex32(row.leaf_hashes[i]), &leaf.leaf_hash);
        const want = try hexAlloc(row.control_blocks[i]);
        defer ta.free(want);
        try testing.expectEqual(want.len, info.controlBlockLen(i));
        try testing.expectEqual(@as(usize, 33) + 32 * leaf.path.len, want.len);
        const got = try info.controlBlockAlloc(ta, i);
        defer ta.free(got);
        try testing.expectEqualSlices(u8, want, got);
    }
    return info.leaves.len;
}

test "BIP341 vectors: explicit shape reproduces every published value and control block" {
    var checked: usize = 0;
    for (v.rows) |row| {
        const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(row.internal_pubkey));
        var info = try tree.buildFromTree(ta, internal, &row.tree);
        defer info.deinit(ta);
        checked += try checkRow(row, info);
    }
    try testing.expectEqual(@as(usize, v.control_block_count), checked);
    try testing.expectEqual(@as(usize, 12), checked);
}

test "BIP341 vectors: depth-list form gives the same results as the explicit form" {
    for (v.rows) |row| {
        const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(row.internal_pubkey));
        var a = try tree.buildFromTree(ta, internal, &row.tree);
        defer a.deinit(ta);
        var b = try tree.buildFromLeaves(ta, internal, row.leaves);
        defer b.deinit(ta);
        _ = try checkRow(row, b);
        try testing.expectEqual(a.leaves.len, b.leaves.len);
        for (a.leaves, b.leaves) |x, y| {
            try testing.expectEqualSlices(u8, &x.leaf_hash, &y.leaf_hash);
            try testing.expectEqualSlices([32]u8, x.path, y.path);
        }
    }
}

test "single leaf: root is the leaf hash, empty path, 33-byte control block" {
    const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    const script = [_]u8{0x51};
    var info = try tree.buildFromLeaves(ta, internal, &.{.{ .depth = 0, .script = &script }});
    defer info.deinit(ta);
    try testing.expectEqualSlices(u8, &tree.tapLeafHash(0xc0, &script), &info.merkle_root.?);
    try testing.expectEqual(@as(usize, 0), info.leaves[0].path.len);
    var buf: [33]u8 = undefined;
    const cb = info.controlBlock(0, &buf);
    try testing.expectEqual(@as(usize, 33), cb.len);
    try testing.expectEqual(@as(u8, 0xc0 | @as(u8, info.output.parity)), cb[0]);
    try testing.expectEqualSlices(u8, &internal.toBytes(), cb[1..]);
}

test "empty tree is key-path-only: null root, same output as tweakPublicKey(null)" {
    const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    var info = try tree.buildFromLeaves(ta, internal, &.{});
    defer info.deinit(ta);
    try testing.expect(info.merkle_root == null);
    try testing.expectEqual(@as(usize, 0), info.leaves.len);
    const want = try taproot.tweakPublicKey(internal, null);
    try testing.expectEqualSlices(u8, &want.output.x, &info.output.x);
    var info2 = try tree.buildFromTree(ta, internal, null);
    defer info2.deinit(ta);
    try testing.expectEqualSlices(u8, &want.output.x, &info2.output.x);
}

test "tapBranchHash is symmetric; tapLeafHash commits to version and script" {
    const a = try hex32(v.rows[3].leaf_hashes[0]);
    const b = try hex32(v.rows[3].leaf_hashes[1]);
    try testing.expectEqualSlices(u8, &tree.tapBranchHash(a, b), &tree.tapBranchHash(b, a));
    try testing.expect(!std.mem.eql(u8, &tree.tapLeafHash(0xc0, "x"), &tree.tapLeafHash(0xc2, "x")));
    try testing.expect(!std.mem.eql(u8, &tree.tapLeafHash(0xc0, "x"), &tree.tapLeafHash(0xc0, "y")));
}

test "leaf script longer than 252 bytes uses a multi-byte CompactSize" {
    // 300-byte script: prefix fd 2c 01. Compare against a manual tagged hash.
    var script: [300]u8 = undefined;
    @memset(&script, 0xab);
    var h = bip340.hash.taggedHasher("TapLeaf");
    h.update(&[_]u8{ 0xc0, 0xfd, 0x2c, 0x01 });
    h.update(&script);
    try testing.expectEqualSlices(u8, &h.finalResult(), &tree.tapLeafHash(0xc0, &script));
}

fn internalKey() !bip340.XOnlyPublicKey {
    return bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
}

test "invalid depth lists are typed errors" {
    const k = try internalKey();
    const s = "\x51";
    const L = tree.DepthLeaf;
    // Incomplete: a lone depth-1 leaf, a missing sibling.
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{L{ .depth = 1, .script = s }}));
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 2, .script = s } }));
    // Overfull: a depth-0 leaf is the whole tree.
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 0, .script = s }, L{ .depth = 0, .script = s } }));
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 1, .script = s }, L{ .depth = 1, .script = s } }));
    // Wrong depth-first order (2,1,2 never completes).
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 2, .script = s }, L{ .depth = 1, .script = s }, L{ .depth = 2, .script = s } }));
    // Valid: 1,2,2 and 2,2,1.
    var ok = try tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 2, .script = "\x52" }, L{ .depth = 2, .script = "\x53" } });
    ok.deinit(ta);
    var ok2 = try tree.buildFromLeaves(ta, k, &.{ L{ .depth = 2, .script = s }, L{ .depth = 2, .script = "\x52" }, L{ .depth = 1, .script = "\x53" } });
    ok2.deinit(ta);
}

test "invalid leaf versions are typed errors" {
    const k = try internalKey();
    for ([_]u8{ 0xc1, 0x01, 0xff, 0x50 }) |ver| {
        try testing.expectError(error.InvalidLeafVersion, tree.buildFromLeaves(ta, k, &.{.{ .depth = 0, .version = ver, .script = "\x51" }}));
        const n: tree.Node = .{ .leaf = .{ .version = ver, .script = "\x51" } };
        try testing.expectError(error.InvalidLeafVersion, tree.buildFromTree(ta, k, &n));
    }
    // Even versions other than 0xc0 (incl. 0x00 and 0xfa from the vectors) are fine.
    for ([_]u8{ 0x00, 0x52, 0xfa, 0xfe }) |ver| {
        var info = try tree.buildFromLeaves(ta, k, &.{.{ .depth = 0, .version = ver, .script = "\x51" }});
        defer info.deinit(ta);
        try testing.expectEqual(ver, info.leaves[0].version);
    }
}

test "depth limit: 128 accepted, 129 rejected (list and explicit)" {
    const k = try internalKey();
    const s = "\x51";
    // A degenerate ("comb") tree of depth d: leaves at depths 1,2,...,d,d.
    const build = struct {
        fn run(d: u8, alloc: std.mem.Allocator) !?tree.SpendInfo {
            var list = try alloc.alloc(tree.DepthLeaf, d + 1);
            defer alloc.free(list);
            for (0..d) |i| list[i] = .{ .depth = @intCast(i + 1), .script = "\x51" };
            list[d] = .{ .depth = d, .script = "\x52" };
            return try tree.buildFromLeaves(alloc, kk(), list);
        }
        fn kk() bip340.XOnlyPublicKey {
            return bip340.XOnlyPublicKey.fromBytes(hex32(v.rows[0].internal_pubkey) catch unreachable) catch unreachable;
        }
    };
    _ = s;
    var ok = (try build.run(128, ta)).?;
    defer ok.deinit(ta);
    try testing.expectEqual(@as(usize, 128), ok.leaves[127].path.len);
    try testing.expectEqual(@as(usize, 33 + 32 * 128), ok.controlBlockLen(127));
    try testing.expectError(error.TreeTooDeep, build.run(129, ta));
    try testing.expectError(error.TreeTooDeep, tree.buildFromLeaves(ta, k, &.{.{ .depth = 255, .script = "\x51" }}));

    // Explicit: a right-leaning chain of 129 branches is too deep, 128 fine.
    var nodes: [131]tree.Node = undefined;
    const leaf: tree.Node = .{ .leaf = .{ .script = "\x51" } };
    nodes[0] = leaf;
    for (1..131) |i| nodes[i] = .{ .branch = .{ &leaf, &nodes[i - 1] } };
    var deep_ok = try tree.buildFromTree(ta, k, &nodes[128]);
    deep_ok.deinit(ta);
    try testing.expectError(error.TreeTooDeep, tree.buildFromTree(ta, k, &nodes[129]));
}

test "no leaks on the error paths (testing.allocator checks)" {
    const k = try internalKey();
    const L = tree.DepthLeaf;
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = "\x51" }, L{ .depth = 1, .script = "\x51" }, L{ .depth = 0, .script = "\x51" } }));
    // Allocation failure at every point.
    const list = [_]L{ .{ .depth = 1, .script = "\x51" }, .{ .depth = 2, .script = "\x52" }, .{ .depth = 2, .script = "\x53" } };
    var fail: usize = 0;
    while (fail < 40) : (fail += 1) {
        var fa = testing.FailingAllocator.init(ta, .{ .fail_index = fail });
        if (tree.buildFromLeaves(fa.allocator(), k, &list)) |ok| {
            var info = ok;
            info.deinit(fa.allocator());
        } else |err| try testing.expectEqual(error.OutOfMemory, err);
    }
}

const build_seeds = [_][]const u8{
    "",
    "\x02\x01\x00\x03abc\x01\x00\x03def",
    "\x03\x01\x00\x01a\x02\x00\x01b\x02\x00\x01c",
    "\x02\x00\x00\x00\x00\x00\x00",
    "\x01\xfa\x50\x02xy",
    "\x08\x01\x01\x01\x02\x02\x02\x03\x03\x03\x04\x04\x04\x04\x04\x04\x04",
};

test "fuzz: buildFromLeaves never panics; success implies a complete tree with matching paths" {
    try testing.fuzz({}, fuzzBuild, .{ .corpus = &build_seeds });
}

fn fuzzBuild(_: void, smith: *std.testing.Smith) !void {
    var scripts: [8][16]u8 = undefined;
    var list: [8]tree.DepthLeaf = undefined;
    // Full-width draws reduced by hand: a `u8` draw reads eight input bytes
    // and answers its minimum unless they already fit, which collapsed every
    // seed into one input (`check-fuzz-reach` R1; testkit/src/fuzz.zig).
    const n: usize = @intCast(smith.value(u64) % 9);
    for (0..n) |i| {
        const raw: u8 = @truncate(smith.value(u64));
        const depth: u8 = if (raw >= 250) raw - 120 else raw % 5; // 0..4, or 130..135 (too deep)
        const len = smith.slice(&scripts[i]);
        list[i] = .{ .depth = depth, .version = @truncate(smith.value(u64)), .script = scripts[i][0..len] };
    }
    const k = try internalKey();
    var info = tree.buildFromLeaves(ta, k, list[0..n]) catch return;
    defer info.deinit(ta);
    try testing.expectEqual(n, info.leaves.len);
    if (n == 0) return try testing.expect(info.merkle_root == null);
    var kraft: u32 = 0; // sum of 2^(4-depth) must be exactly 2^4: a complete tree
    for (info.leaves, list[0..n]) |leaf, l| {
        try testing.expect(l.depth <= 4);
        try testing.expectEqual(@as(usize, l.depth), leaf.path.len);
        try testing.expect(tree.validLeafVersion(l.version));
        kraft += @as(u32, 1) << @intCast(4 - l.depth);
    }
    try testing.expectEqual(@as(u32, 16), kraft);
}
